```

You need to *either provide a working module* under `./src/components/` or *remove reference* if deprecated.

---

## 🛠️ SOLUTION: FULL CODE — `AgentChangeDetector.tsx`

**Path:** `/var/www/llama-dashboard/src/components/AgentChangeDetector.tsx`

```tsx
'use client';

import React, { useEffect, useState } from 'react';

// 🚨 This file checks continuity via memory identity hash or session fingerprint
export default function AgentChangeDetector() {
  const [status, setStatus] = useState<'ok' | 'changed' | 'unknown'>('unknown');

  useEffect(() => {
    const controller = new AbortController();

    async function checkAgentChange() {
      try {
        const res = await fetch(`/agents/health`, { signal: controller.signal });
        if (!res.ok) throw new Error('Failed health check');
        const data = await res.json();

        // 📍 Optional: replace with actual logic for detecting state hash deviation
        const currentInstance = localStorage.getItem('agent_instance_id');
        const serverInstance = data.instance_id;
        if (!currentInstance) {
          localStorage.setItem('agent_instance_id', serverInstance);
          setStatus('ok');
        } else {
          setStatus(currentInstance === serverInstance ? 'ok' : 'changed');
        }
      } catch {
        setStatus('unknown');
      }
    }

    checkAgentChange();

    return () => controller.abort();
  }, []);

  const statusColor = status === 'ok'
    ? 'text-green-400'
    : status === 'changed'
    ? 'text-yellow-400'
    : 'text-red-400';

  return (
    <div className="p-4 bg-zinc-800 rounded-xl">
      <h2 className="text-lg font-semibold">Agent Change Detector</h2>
      <p className={`mt-1 font-mono ${statusColor}`}>
        Status: {status}
      </p>
    </div>
  );
}
```

